# ! [feature (proc_macro_hygiene , decl_macro)] # [macro_use] extern crate rocket ; # [macro_use] extern crate rocket_include_static_resources ; use rocket_include_static_resources :: StaticResponse ; # [get ("/favicon.ico")] fn favicon () -> StaticResponse { static_response ! ("static/favicon.ico") } # [get ("/<name>/<age>")] fn hello (name : String , age : u8) -> String { format ! ("Hello, {} year old named {}!" , age , name) } fn main () { rocket :: ignite () . mount ("/hello" , routes ! [hello]) . launch () ; }